import { brandTokenNames, colorNames, colors, type ColorSet } from '../colors';
import { publicSite } from '../public-site';
import { radius, scrim, shadow, type ShadowName } from '../shape';
import { themeColorNames } from '../theme-colors';
import { fontFamily } from '../type';

const HEADER =
  '/* GENERATED by pnpm tokens:build — do not edit. Source: packages/tokens/src */\n' +
  '/* A school brand colour is set on an element with data-school-brand, as --school-light-<token> and\n' +
  '   --school-dark-<token> for each brand token (from deriveBrand, computed by the API). */\n';

type Decl = [name: string, value: string];
type Theme = 'light' | 'dark';

const siteNames = Object.keys(publicSite.light) as (keyof typeof publicSite.light)[];
const shadowNames = Object.keys(shadow.light) as ShadowName[];

/** All `--quad-*` declarations for one theme. */
function themeDecls(theme: Theme): Decl[] {
  const set: ColorSet = colors[theme];
  const decls: Decl[] = colorNames.map((name): Decl => [`--quad-${name}`, set[name]]);
  for (const name of shadowNames) decls.push([`--quad-shadow-${name}`, shadow[theme][name]]);
  decls.push(['--quad-scrim', scrim[theme]]);
  for (const name of siteNames) decls.push([`--quad-site-${name}`, publicSite[theme][name]]);
  return decls;
}

/** The school's brand for one theme: each brand token reads the value the shell set inline. */
function schoolBrandDecls(theme: Theme): Decl[] {
  return brandTokenNames.map((name): Decl => [`--quad-${name}`, `var(--school-${theme}-${name})`]);
}

function block(selector: string, decls: Decl[], indent = ''): string {
  const lines = decls.map(([n, v]) => `${indent}  ${n}: ${v};`);
  return `${indent}${selector} {\n${lines.join('\n')}\n${indent}}\n`;
}

/**
 * `:root`, dark and school-brand variable blocks (no Tailwind syntax).
 * The light and dark blocks also match any element with `data-theme`, so a container can force either theme
 * inside a page in the other one (the /design style guide shows each component in both side by side).
 * The school's brand applies on `[data-school-brand]` (the staff shell and <html>), for both themes, so
 * switching theme needs no recalculation (spec 03 "Runtime").
 */
export function buildVariableBlocks(): string {
  const light = [['color-scheme', 'light'] as Decl, ...themeDecls('light')];
  const dark = [['color-scheme', 'dark'] as Decl, ...themeDecls('dark')];
  const systemDark = ':root:not([data-theme="light"])';

  return [
    block(':root,\n[data-theme="light"]', light),
    block('[data-theme="dark"]', dark),
    `@media (prefers-color-scheme: dark) {\n${block(systemDark, dark, '  ')}}\n`,
    '/* The school brand colour (spec 03 "School brand colour"). */',
    block('[data-school-brand]', schoolBrandDecls('light')),
    `@media (prefers-color-scheme: dark) {\n${block(
      `${systemDark}[data-school-brand],\n  ${systemDark} [data-school-brand]`,
      schoolBrandDecls('dark'),
      '  ',
    )}}\n`,
    block(
      '[data-theme="dark"][data-school-brand],\n[data-theme="dark"] [data-school-brand]',
      schoolBrandDecls('dark'),
    ),
    block(
      '[data-theme="light"][data-school-brand],\n[data-theme="light"] [data-school-brand]',
      schoolBrandDecls('light'),
    ),
    '/* Public site accent: lime for schools, pink for parents (data-view on <html>, spec 19). */',
    block(':root', [['--quad-site-accent', `var(--quad-site-${publicSite.accent.school})`]]),
    block(':root[data-view="parent"]', [
      ['--quad-site-accent', `var(--quad-site-${publicSite.accent.parent})`],
    ]),
  ].join('\n');
}

/** Variables only, for consumers that do not use Tailwind. */
export function buildTokensCss(): string {
  return `${HEADER}\n${buildVariableBlocks()}`;
}

/** Tailwind v4 theme: utilities read the runtime `--quad-*` variables. */
export function buildThemeCss(): string {
  const colorLines = themeColorNames.map((n) => `  --color-${n}: var(--quad-${n});`);
  const radiusLines = Object.entries(radius).map(([n, v]) => `  --radius-${n}: ${v}px;`);
  const shadowLines = shadowNames.map((n) => `  --shadow-${n}: var(--quad-shadow-${n});`);
  const theme = [
    '@theme inline {',
    ...colorLines,
    '  --color-scrim: var(--quad-scrim);',
    ...radiusLines,
    ...shadowLines,
    `  --font-sans: ${fontFamily.sans};`,
    `  --font-display: ${fontFamily.display};`,
    '}\n',
  ].join('\n');
  return `${HEADER}\n${theme}\n${buildVariableBlocks()}`;
}
